pub fn skip_unquoted_value(&mut self) -> Result<(), ReaderError> {
        loop {
            unsafe {
                let mut ptr: *const u8 = self.buf.start;
                let end: *const u8 = self.buf.end;

                if end.offset_from(ptr) >= 4 {
                    let word: u32 = ptr.cast::<u32>().read_unaligned().to_le();

                    // 50% of EU4 values followed by this whitespace sequence
                    if word == 0x0909090A {
                        // \n\t\t\t
                        ptr = ptr.add(4);
                    }
                }

                while ptr < end {
                    match *ptr {
                        b'{' => {
                            self.buf.advance_to(ptr.add(1));
                            return self.skip_container();
                        }
                        b' ' | b'\t' | b'\n' | b'\r' | b';' => {
                            ptr = ptr.add(1);
                        }
                        _ => return Ok(()),
                    }
                }

                self.buf.advance_to(end);
                match self.buf.fill_buf(&mut self.reader) {
                    Ok(0) => return Ok(()),
                    Err(e: BufferError) => return Err(self.buffer_error(e)),
                    Ok(_) => {}
                }
            }
        }
    }

