pub fn read(&mut self) -> Result<Token, ReaderError> {
        let s = std::ptr::addr_of!(self);
        match unsafe { self.next_opt() } {
            (Some(x), _) => Ok(x),
            (None, None) => Err(unsafe { (*s).eof_error() }),
            (None, Some(e)) => Err(e),
        }
    }

